UPDATE articles SET title_zhcn = "\u672a\u6765\u6d3b\u52a8\uff1a\u4e9a\u6d32\u79c1\u4eba\u94f6\u884c\u5bb6\u53e6\u7c7b\u6295\u8d44\u5cf0\u4f1a 2026", excerpt_zhcn = "\u4e9a\u6d32\u79c1\u4eba\u94f6\u884c\u5bb6\u53e6\u7c7b\u6295\u8d44\u5cf0\u4f1a 2026 \u6c47\u805a\u79c1\u4eba\u94f6\u884c\u53ca\u5bb6\u65cf\u529e\u516c\u5ba4\u4e13\u5bb6\uff0c\u63a2\u8ba8\u53e6\u7c7b\u6295\u8d44\u7b56\u7565\u4e0e\u673a\u9047\u3002" WHERE id = 'ee05c0c8-13bb-4066-8092-d52ee6fdf937';
UPDATE articles SET title_zhcn = "\u63d0\u65e9\u8fbe\u6807\uff01\u903e200\u95f4\u5bb6\u65cf\u529e\u516c\u5ba4\u843d\u6237\u9999\u6e2f", excerpt_zhcn = "\u8d22\u7ecf\u4e8b\u52a1\u53ca\u5e93\u52a1\u5c40\u5ba3\u5e03\uff0c\u5728\u6295\u8d44\u63a8\u5e7f\u7f72\u534f\u52a9\u4e0b\uff0c\u81f3\u4eca\u6765\u6e2f\u843d\u6237\u6216\u6269\u5c55\u4e1a\u52a1\u7684\u5bb6\u65cf\u529e\u516c\u5ba4\u6570\u76ee\u5df2\u7a81\u7834200\u95f4\uff0c\u8d85\u524d\u5b8c\u62102022\u5e74\u300a\u65bd\u653f\u62a5\u544a\u300b\u6240\u8ba2\u7acb\u7684\u7ee9\u6548\u6307\u6807\u3002", content_zhcn = "<p>\u8d22\u7ecf\u4e8b\u52a1\u53ca\u5e93\u52a1\u5c409\u670815\u65e5\u5ba3\u5e03\uff0c\u5728\u7279\u533a\u653f\u5e9c\u5927\u529b\u63a8\u52a8\u4e0b\uff0c\u81f3\u4eca\u7ecf\u6295\u8d44\u63a8\u5e7f\u7f72\u534f\u52a9\u6765\u6e2f\u843d\u6237\u6216\u6269\u5c55\u4e1a\u52a1\u7684\u5bb6\u65cf\u529e\u516c\u5ba4\u6570\u76ee\u5df2\u7a81\u7834200\u95f4\uff0c\u8d85\u524d\u5b8c\u62102022\u5e74\u300a\u65bd\u653f\u62a5\u544a\u300b\u6240\u8ba2\u7acb\u7684\u7ee9\u6548\u6307\u6807\uff0c\u4ee4\u9999\u6e2f\u4f5c\u4e3a\u4e9a\u6d32\u9886\u5148\u7684\u8de8\u5883\u79c1\u4eba\u8d22\u5bcc\u7ba1\u7406\u4e2d\u5fc3\u53ca\u5168\u7403\u5bb6\u65cf\u529e\u516c\u5ba4\u67a2\u7ebd\u7684\u5730\u4f4d\u66f4\u4e3a\u7a33\u56fa\u3002</p>\n<p>\u4e3a\u5f3a\u5316\u9999\u6e2f\u8d44\u4ea7\u53ca\u8d22\u5bcc\u7ba1\u7406\u4e1a\u8fd9\u91cd\u8981\u7684\u91d1\u878d\u589e\u957f\u9886\u57df\uff0c\u884c\u653f\u957f\u5b98\u4e8e2022\u5e74\u5728\u5176\u9996\u4efd\u300a\u65bd\u653f\u62a5\u544a\u300b\u4fbf\u63d0\u51fa\u57282025\u5e74\u5e74\u5e95\u524d\u63a8\u52a8\u4e0d\u5c11\u4e8e200\u95f4\u5bb6\u529e\u5728\u6e2f\u8bbe\u7acb\u6216\u6269\u5c55\u4e1a\u52a1\u7684\u660e\u786e\u76ee\u6807\u3002</p>\n<p>\u516b\u5927\u63aa\u65bd\u8054\u5408\u53d1\u529b</p>\n<p>\u8d22\u5e93\u5c40\u968f\u540e\u4e8e2023\u5e743\u6708\u53d1\u8868\u653f\u7b56\u5ba3\u8a00\uff0c\u5c55\u793a\u653f\u5e9c\u79ef\u6781\u5b8c\u5584\u5bb6\u65cf\u529e\u516c\u5ba4\u548c\u8d44\u4ea7\u62e5\u6709\u4eba\u7684\u751f\u6001\u5708\u7684\u51b3\u5fc3\uff0c\u5e76\u900f\u8fc7\u63a8\u51fa\u516b\u5927\u63aa\u65bd\uff0c\u5305\u62ec\u63d0\u4f9b\u7a0e\u52a1\u4f18\u60e0\u3001\u5f15\u5165\u300c\u65b0\u8d44\u672c\u6295\u8d44\u8005\u5165\u5883\u8ba1\u5212\u300d\u3001\u8bbe\u7acb\u9999\u6e2f\u8d22\u5bcc\u4f20\u627f\u5b66\u9662\u7b49\uff0c\u4e3a\u5f00\u62d3\u5bb6\u65cf\u529e\u516c\u5ba4\u76f8\u5173\u4ea7\u4e1a\u6253\u9020\u6700\u5177\u7ade\u4e89\u529b\u7684\u6709\u5229\u73af\u5883\u3002</p>\n<p>\u540c\u65f6\uff0c\u6295\u8d44\u63a8\u5e7f\u7f72\u7684FamilyOfficeHK\u4e13\u8d23\u56e2\u961f\u4e5f\u6269\u5927\u804c\u80fd\uff0c\u5e76\u5efa\u7acb\u65b0\u7684\u5bb6\u65cf\u529e\u516c\u5ba4\u670d\u52a1\u63d0\u4f9b\u8005\u7f51\u7edc\uff0c\u96c6\u5408\u5404\u76f8\u5173\u4e13\u4e1a\u670d\u52a1\u9886\u57df\u7684\u56e2\u961f\uff0c\u4e3a\u5bb6\u529e\u63d0\u4f9b\u66f4\u5168\u9762\u7684\u670d\u52a1\u548c\u534f\u52a9\u3002\u4e13\u8d23\u56e2\u961f\u4ea6\u5728\u4e16\u754c\u5404\u5730\u52a0\u5f3a\u5ba3\u4f20\u548c\u4e3e\u529e\u4ee5\u5bb6\u529e\u4e3a\u4e3b\u9898\u7684\u6d3b\u52a8\uff0c\u5305\u62ec\u5728\u5185\u5730\u3001\u6b27\u6d32\u548c\u4e1c\u5357\u4e9a\u56fd\u5bb6\u8054\u76df\uff08\u4e1c\u76df\uff09\u7b49\u5730\u533a\u8fdb\u884c\u8def\u6f14\uff0c\u5e76\u5728\u5168\u7403\u4e3b\u8981\u5e02\u573a\u53d1\u8868\u4e13\u9898\u6587\u7ae0\uff0c\u4e3b\u52a8\u4e0e\u6709\u610f\u5728\u6e2f\u843d\u6237\u7684\u8d85\u9ad8\u8d44\u4ea7\u51c0\u503c\u4eba\u58eb\u63a5\u6d3d\u3002\u800c\u653f\u5e9c\u6bcf\u5e74\u4e3e\u529e\u7684\u65d7\u8230\u5bb6\u529e\u6d3b\u52a8\u300c\u88d5\u6cfd\u9999\u6c5f\u300d\u9ad8\u5cf0\u8bba\u575b\u4ea6\u6c47\u805a\u4f17\u591a\u5168\u7403\u5177\u5f71\u54cd\u529b\u7684\u5bb6\u529e\u51b3\u7b56\u4eba\u6765\u6e2f\u3002</p>\n<p>\u6709\u89c1\u300c\u65b0\u8d44\u672c\u6295\u8d44\u8005\u5165\u5883\u8ba1\u5212\u300d\u81ea\u63a8\u51fa\u4ee5\u6765\u751a\u53d7\u76f8\u5173\u5ba2\u6237\u7fa4\u9752\u7750\uff0c\u7279\u533a\u653f\u5e9c\u4eca\u5e743\u6708\u66f4\u4f18\u5316\u8be5\u8ba1\u5212\uff0c\u8fdb\u4e00\u6b65\u589e\u5f3a\u9999\u6e2f\u5bf9\u5168\u7403\u9ad8\u51c0\u503c\u4eba\u58eb\u6765\u6e2f\u6295\u8d44\u53ca\u843d\u6237\u7684\u5438\u5f15\u529b\u3002\u76f8\u5173\u4f18\u5316\u63aa\u65bd\u5305\u62ec\u7533\u8bf7\u4eba\u900f\u8fc7\u5177\u8d44\u683c\u5355\u4e00\u5bb6\u529e\u7ba1\u7406\u5e76\u7531\u7533\u8bf7\u4eba\u5168\u8d44\u62e5\u6709\u7684\u79c1\u4eba\u516c\u53f8\u6240\u6301\u6709\u7684\u83b7\u8bb8\u6295\u8d44\u8d44\u4ea7\u4ea6\u53ef\u8ba1\u7b97\u5165\u5408\u8d44\u683c\u6295\u8d44\u91d1\u989d\u5185\u3002</p>\n<p>\u6e2f\u8d44\u4ea7\u7ba1\u7406\u603b\u503c\u5e74\u589e13%</p>\n<p>\u8fc7\u53bb\u4e24\u5e74\u591a\u6765\uff0c\u516b\u5927\u63aa\u65bd\u8054\u5408\u4ea7\u751f\u5f3a\u5927\u5438\u5f15\u529b\u3002\u7ecf\u6295\u8d44\u63a8\u5e7f\u7f72\u534f\u52a9\u6765\u6e2f\u843d\u6237\u6216\u6269\u5c55\u7684\u5bb6\u529e\u81ea2022\u5e74\u81f3\u4eca\u5df2\u903e200\u95f4\uff0c\u6b64\u6570\u5b57\u8fd8\u672a\u6db5\u76d6\u81ea\u884c\u6216\u900f\u8fc7\u9999\u6e2f\u4e13\u4e1a\u670d\u52a1\u7f51\u7edc\u800c\u843d\u6237\u7684\u5bb6\u529e\uff0c\u6545\u6b64\u9999\u6e2f\u4f5c\u4e3a\u5bb6\u529e\u67a2\u7ebd\u7684\u5b9e\u9645\u53d1\u5c55\u89c4\u6a21\u5176\u5b9e\u66f4\u4e3a\u53ef\u89c2\u3002\u800c\u4f5c\u4e3a\u4e9a\u6d32\u6700\u5927\u7684\u8de8\u5883\u8d22\u5bcc\u7ba1\u7406\u4e2d\u5fc3\uff0c\u9999\u6e2f\u7684\u8d44\u4ea7\u7ba1\u7406\u603b\u503c\u4e8e2024\u5e74\u5e74\u5e95\u4e5f\u7a81\u783435\u4e07\u4ebf\u6e2f\u5143\uff0c\u6309\u5e74\u589e\u957f13%\uff0c\u51c0\u8d44\u91d1\u6d41\u5165\u66f4\u5927\u5e45\u4e0a\u5347\u903e80%\u81f37050\u4ebf\u6e2f\u5143\uff0c\u53cd\u6620\u9999\u6e2f\u4f5c\u4e3a\u56fd\u9645\u8d44\u4ea7\u914d\u7f6e\u4e2d\u5fc3\u7684\u9b45\u529b\u6301\u7eed\u589e\u5f3a\u3002</p>" WHERE id = '2f621924-4881-46a0-b396-4a84d6573bf0';

